		{"boolean", true},
		{"array", []any{}},
		{"object", map[string]any{}},
		{"empty", ""},
		{"offset", "2026-10-28T00:00:00+00:00"},
		{"submicrosecond", "2026-10-28T00:00:00.123456789Z"},
	}
	if unconfiguredInvalid {
		values = append(values, resourceCASInvalidRevision{"unconfigured", "unconfigured"})
	}
	return values
}

