    let fresh: Awaited<ReturnType<typeof readApplicationAuthority>>;
    try { fresh = await readFresh(signal); } catch {
      return unavailableUpdaterAuthority(updaterAuthorityFingerprint([actionID, targetID, "unavailable"]));
