  for (const vocabulary of authority.vocabularies) {
    assert.equal(vocabularyIds.has(vocabulary.id), false, `duplicate vocabulary ${vocabulary.id}`);
    assert.equal(authorityIds.has(vocabulary.authorityId), true, `${vocabulary.id} has no source authority`);
    assert.equal(sha256(vocabulary.excerpt), vocabulary.excerptSha256, `${vocabulary.id} excerpt digest`);
    vocabularyIds.add(vocabulary.id);

    const entries = extractVocabulary(vocabulary);
    assert.notEqual(entries.length, 0, `${vocabulary.id} extracted no values`);
    assert.equal(new Set(entries.map((entry) => entry.symbol)).size, entries.length, `${vocabulary.id} has duplicate symbols`);
    assert.equal(new Set(entries.map((entry) => entry.value)).size, entries.length, `${vocabulary.id} has duplicate values`);
    const bySymbol = new Map(entries.map((entry) => [entry.symbol, entry.value]));
    const assignedSymbols = new Set<string>();

    for (const projection of vocabulary.domains) {
      assert.equal(domains.has(projection.name), false, `duplicate domain authority ${projection.name}`);
      const symbols = projection.include === "all"
        ? entries.map((entry) => entry.symbol)
        : projection.symbols;
      assert.equal(Array.isArray(symbols), true, `${vocabulary.id}:${projection.name} has no symbols`);
      assert.ok(symbols);
      const values: string[] = [];
      for (const symbol of symbols) {
        assert.equal(bySymbol.has(symbol), true, `${vocabulary.id}:${projection.name} invents ${symbol}`);
        assert.equal(assignedSymbols.has(symbol), false, `${vocabulary.id} assigns ${symbol} twice`);
        assignedSymbols.add(symbol);
        const value = bySymbol.get(symbol);
        assert.ok(value !== undefined);
        values.push(value);
      }
      assert.equal(new Set(values).size, values.length, `${projection.name} contains duplicate values`);
      domains.set(projection.name, Object.freeze(values));
    }

    for (const symbol of vocabulary.sentinelSymbols) {
      assert.equal(bySymbol.has(symbol), true, `${vocabulary.id} invents sentinel ${symbol}`);
      assert.equal(assignedSymbols.has(symbol), false, `${vocabulary.id} reuses sentinel ${symbol}`);
      assignedSymbols.add(symbol);
    }
    assert.deepEqual(
      [...assignedSymbols].sort(),
      entries.map((entry) => entry.symbol).sort(),
      `${vocabulary.id} must partition every source symbol into a domain or explicit unknown sentinel`,
    );
  }
  return domains;
}

export function compareStatusMappingInventory(authority: StatusAuthority, mappingFixture: { domains?: unknown; mappings?: unknown }) {
  const expected = deriveStatusAuthorityDomains(authority);
  const errors = [];
  const fixtureDomains = Array.isArray(mappingFixture.domains) ? mappingFixture.domains : [];
  const mappings: unknown[] = Array.isArray(mappingFixture.mappings) ? mappingFixture.mappings : [];
  if (!sameStrings(fixtureDomains, [...expected.keys()])) {
    errors.push("domain inventory differs from source authority");
  }

  const actual = new Map<string, string[]>();
  const seen = new Set<string>();
  for (const mapping of mappings) {
    if (!mapping || typeof mapping !== "object"
      || !("domain" in mapping) || !("wireValue" in mapping)
      || typeof mapping.domain !== "string"
      || typeof mapping.wireValue !== "string") {
      errors.push("malformed mapping row");
      continue;
    }
    const key = `${mapping.domain}\u0000${mapping.wireValue}`;
    if (seen.has(key)) errors.push(`duplicate mapping ${mapping.domain}:${mapping.wireValue}`);
    seen.add(key);
    const values = actual.get(mapping.domain) || [];
    values.push(mapping.wireValue);
    actual.set(mapping.domain, values);
  }

  for (const [domain, values] of expected) {
    const mapped = actual.get(domain) || [];
    if (!sameStrings(mapped, values)) errors.push(`${domain} values differ from source authority`);
  }
  for (const domain of actual.keys()) {
    if (!expected.has(domain)) errors.push(`unowned mapping domain ${domain}`);
  }
  return Object.freeze(errors);
}

export function verifyStatusAuthoritySources(webRoot: string, authority: StatusAuthority) {
  const controlPanelRoot = resolve(webRoot, "..");
  const repositoryRoots: Readonly<Record<string, string | undefined>> = Object.freeze({
    "Autostream-ControlPanel": controlPanelRoot,
    "Autostream-Contracts": process.env.AUTOSTREAM_STATUS_CONTRACTS_ROOT || resolve(controlPanelRoot, "..", "Autostream-Contracts"),
    "Autostream-Observability": resolve(controlPanelRoot, "..", "Autostream-Observability"),
  });
  let verifiedSources = 0;
  let verifiedControlPanelSources = 0;
  const unavailableSources = [];
  for (const source of authority.authorities) {
    const root = repositoryRoots[source.repository];
    assert.equal(typeof root, "string", `unknown authority repository ${source.repository}`);
    assert.ok(typeof root === "string");
    if (["contracts", "control-panel-stream-store", "control-panel-auth-store"].includes(source.id)) {
      assert.equal(source.currentSource?.objectKind, "commit", `${source.id}: current code-commit source metadata is required after responsibility extraction`);
      assert.ok(source.currentSource);
      assert.match(source.currentSource.revision, /^[a-f0-9]{40}$/);
      const commit = execFileSync("git", ["-C", root, "rev-parse", "--verify", `${source.currentSource.revision}^{commit}`], { encoding: "utf8" }).trim();
      assert.equal(commit, source.currentSource.revision, `${source.id}: current authority must name the exact code commit`);
      verifyStatusAuthoritySourceLocators(root, source.id, commit, source.currentSource.locators, authority.vocabularies);
      for (const locator of source.currentSource.locators) {
        const current: Buffer = source.repository === "Autostream-ControlPanel" && source.id === "control-panel-stream-store" && locator.path === "internal/store/stream_queries_mariadb.go"
          ? (() => {
            const currentRaw: Buffer = readFileSync(join(root, locator.path));
            // Reviewed settings-revision projection only. This independent raw
            // pin prevents a future outer-fixture refresh from hiding status edits.
            assert.equal(sha256(currentRaw), "e150c7afc136eddd09c9cd7c7307f5b1ac9e4539ae96e3166e5fff852ef948ff", `${source.id}:${locator.path} current product source digest`);
            const beforePolling = (() => {
              try { return createPollingCurrentAdapter(controlPanelRoot).inverse(locator.path, currentRaw); }
              catch (cause) { throw new Error(`${source.id}:${locator.path} current product source digest`, { cause }); }
            })();
            return inverseR9ArchiveProcessingSource(
              execFileSync("git", ["-C", root, "cat-file", "blob", `a9efbed3e058bf016b171e50c22650075f20ef50:${locator.path}`]),
              beforePolling,
            );
          })()
          : execFileSync("git", ["-C", root, "cat-file", "blob", `HEAD:${locator.path}`]);
        assert.equal(sha256(current), locator.sourceSha256, `${source.id}:${locator.path} current product source digest`);
      }
      verifiedSources += 1;
      if (source.repository === "Autostream-ControlPanel") verifiedControlPanelSources += 1;
      continue;
    }
    const path = join(root, ...source.path.split("/"));
    if (!existsSync(path)) {
      unavailableSources.push(`${source.repository}:${source.path}`);
      continue;
    }
    const currentBytes = readFileSync(path);
    let bytes: Buffer = currentBytes;
    if (source.repository === "Autostream-ControlPanel" && source.id === "control-panel-domain" && source.path === "web/src/types/domain.ts") {
      const historical = (() => {
        try { return createPollingCurrentAdapter(controlPanelRoot).inverse(source.path, currentBytes); }
        catch (cause) { throw new Error(`${source.repository}:${source.path} source digest`, { cause }); }
      })();
      assert.ok(historical, "status domain must have its immutable pre-polling source");
      // Independently permit only these two optional metadata lines. A refreshed
      // outer fixture cannot conceal any status vocabulary or other source edit.
      let withoutMetadata = normalizeNewlines(currentBytes.toString("utf8"));
      for (const property of ["settings_revision", "metadata_revision"]) {
        const line = `  ${property}?: string;\n`;
        assert.equal(withoutMetadata.split(line).length, 2, `${property}: exactly one optional metadata field is permitted`);
        withoutMetadata = withoutMetadata.replace(line, "");
      }
      assert.equal(withoutMetadata, normalizeNewlines(historical.toString("utf8")), "status domain may differ only by the two optional polling metadata fields");
      for (const vocabulary of authority.vocabularies.filter((entry) => entry.authorityId === source.id)) {
        assert.ok(normalizeNewlines(currentBytes.toString("utf8")).includes(normalizeNewlines(vocabulary.excerpt)), `${vocabulary.id}: actual current status vocabulary changed`);
      }
      bytes = historical;
    }
    if (source.repository === "Autostream-ControlPanel" && source.id === "control-panel-http" && source.path === "internal/httpapi/server_status_projection.go") {
      // Reviewed additions: metadata revision and transport fields/projection.
      // Preserve the old status source SHA instead of accepting a refreshed oracle.
      assert.equal(sha256(currentBytes), "3724871d1102e8d4a2d402f2f28b7dca9d98d4755bebabd99f25ccfd5bb264d1", `${source.repository}:${source.path} source digest`);
      const historical = (() => {
        try { return createPollingCurrentAdapter(controlPanelRoot).inverse(source.path, currentBytes); }
        catch (cause) { throw new Error(`${source.repository}:${source.path} source digest`, { cause }); }
      })();
      assert.ok(historical, "HTTP status source must retain its immutable pre-polling bytes");
      for (const vocabulary of authority.vocabularies.filter((entry) => entry.authorityId === source.id)) {
        assert.ok(normalizeNewlines(currentBytes.toString("utf8")).includes(normalizeNewlines(vocabulary.excerpt)), `${vocabulary.id}: actual current status vocabulary changed`);
      }
      bytes = historical;
    }
    assert.equal(sha256(bytes), source.sourceSha256, `${source.repository}:${source.path} source digest`);
    const normalizedSource = normalizeNewlines(bytes.toString("utf8"));
    for (const vocabulary of authority.vocabularies.filter((entry) => entry.authorityId === source.id)) {
      assert.equal(
        normalizedSource.includes(normalizeNewlines(vocabulary.excerpt)),
        true,
        `${vocabulary.id} snapshot is not byte-derived from the fixed source`,
      );
    }
    verifiedSources += 1;
    if (source.repository === "Autostream-ControlPanel") verifiedControlPanelSources += 1;
  }
  assert.equal(verifiedControlPanelSources >= 4, true, "repository-contained Control Panel authority was not verified");
  return Object.freeze({
    verifiedSources,
    verifiedControlPanelSources,
    unavailableSources: Object.freeze(unavailableSources),
    excerptMismatches: 0,
  });
}

function extractVocabulary(vocabulary: StatusVocabulary) {
  switch (vocabulary.parser) {
    case "go-typed-constants":
      return regexEntries(vocabulary.excerpt, /^\s*([A-Za-z]\w*)\s+[A-Za-z]\w*\s*=\s*"([^"]+)"\s*$/gm);
    case "go-untyped-constants":
      return regexEntries(vocabulary.excerpt, /^\s*([A-Za-z]\w*)\s*=\s*"([^"]+)"\s*$/gm);
    case "sql-status-enum": {
      const match = vocabulary.excerpt.match(/\bstatus\s+ENUM\(([^)]+)\)/);
      assert.ok(match, `${vocabulary.id} status ENUM missing`);
      return quotedValues(match[1], vocabulary.id);
    }
    case "ts-string-union":
      return valueEntries([...vocabulary.excerpt.matchAll(/^\s*\|\s*"([^"]+)";?\s*$/gm)].map((match) => match[1]), vocabulary.id);
    case "go-return-literals":
      return valueEntries([...vocabulary.excerpt.matchAll(/\breturn\s+"([^"]+)"/g)].map((match) => match[1]), vocabulary.id);
    case "sql-status-in": {
      const values = [...vocabulary.excerpt.matchAll(/\bstatus\)\)\s+IN\s*\(([^)]+)\)/g)]
        .flatMap((match) => [...match[1].matchAll(/'([^']+)'/g)].map((value) => value[1]));
      return valueEntries(values, vocabulary.id);
    }
    case "go-status-assignments":
      return valueEntries([...vocabulary.excerpt.matchAll(/\bstatus\s*(?::=|=)\s*"([^"]+)"/g)].map((match) => match[1]), vocabulary.id);
    case "go-filter-results":
      return valueEntries([...vocabulary.excerpt.matchAll(/filter\.Result\s*!=\s*"([^"]+)"/g)].map((match) => match[1]), vocabulary.id);
    default:
      assert.fail(`unsupported authority parser ${vocabulary.parser}`);
  }
}

function regexEntries(source: string, pattern: RegExp) {
  return [...source.matchAll(pattern)].map((match) => Object.freeze({ symbol: match[1], value: match[2] }));
}

function quotedValues(source: string, prefix: string) {
  return valueEntries([...source.matchAll(/'([^']+)'/g)].map((match) => match[1]), prefix);
}

function valueEntries(values: readonly string[], prefix: string) {
  return [...new Set(values)].map((value) => Object.freeze({ symbol: `${prefix}:${value}`, value }));
}

function sameStrings(left: readonly unknown[], right: readonly unknown[]) {
  return left.length === right.length
    && new Set(left).size === left.length
    && new Set(right).size === right.length
    && [...left].sort().every((value, index) => value === [...right].sort()[index]);
}

function normalizeNewlines(value: string) {
  return value.replace(/\r\n/g, "\n");
}

function sha256(value: string | Uint8Array) {
  return createHash("sha256").update(value).digest("hex");
}

function record(value: unknown): asserts value is Record<string, unknown> {
  assert.ok(value !== null && typeof value === "object" && !Array.isArray(value), "authority record is missing");
}
function strings(value: unknown): asserts value is string[] {
  assert.ok(Array.isArray(value) && value.every(entry => typeof entry === "string"), "authority string inventory is missing");
}
function assertStatusAuthority(value: unknown): asserts value is StatusAuthority {
  record(value); assert.equal(typeof value.schemaVersion, "number");
  assert.ok(Array.isArray(value.authorities)); assert.ok(Array.isArray(value.vocabularies));
  for (const source of value.authorities) {
    record(source);
    for (const key of ["id", "repository", "branch", "head", "path", "sourceSha256"]) assert.equal(typeof source[key], "string");
    if (source.currentSource !== undefined) {
      record(source.currentSource);
      assert.equal(typeof source.currentSource.objectKind, "string"); assert.equal(typeof source.currentSource.revision, "string");
      assert.ok(Array.isArray(source.currentSource.locators));
      for (const locator of source.currentSource.locators) {
        record(locator); assert.equal(typeof locator.path, "string"); assert.equal(typeof locator.sourceSha256, "string"); strings(locator.vocabularyIds);
      }
    }
  }
  for (const vocabulary of value.vocabularies) {
    record(vocabulary);
    for (const key of ["id", "authorityId", "symbol", "parser", "excerpt", "excerptSha256"]) assert.equal(typeof vocabulary[key], "string");
    strings(vocabulary.sentinelSymbols); assert.ok(Array.isArray(vocabulary.domains));
    for (const projection of vocabulary.domains) {
      record(projection); assert.equal(typeof projection.name, "string");
      if (projection.include !== undefined) assert.equal(typeof projection.include, "string");
      if (projection.symbols !== undefined) strings(projection.symbols);
    }
  }
}

